{
  "components": [
    {
      "type": "claim",
      "quote": "Sectoral planning is an official procedure in which the aim is to determine how a given project can best be embedded in the landscape and meet the spatial planning and environmental protection requirements.",
      "gist": "Sectoral planning is an official process to determine optimal project integration into the landscape while meeting spatial and environmental requirements."
    },
    {
      "type": "claim",
      "quote": "Technical and economic deliberations are incorporated into the process.",
      "gist": "Technical and economic considerations are included in the sectoral planning process."
    },
    {
      "type": "obligation",
      "quote": "Interested parties have the opportunity to submit comments and statements of position within the scope of the consultation and participation procedure.",
      "gist": "Interested parties are entitled to submit comments and statements during consultation and participation."
    },
    {
      "type": "claim",
      "quote": "The sectoral planning procedure is implemented in several stages.",
      "gist": "Sectoral planning is carried out in multiple stages."
    },
    {
      "type": "entity",
      "quote": "Swissgrid AG",
      "gist": "Swissgrid AG (the entity submitting the application, typically the national grid operator)"
    }
  ]
}
